CREATE OR REPLACE FUNCTION nexus.search_aspect_scoped_1024( p_query vector(1024), p_collections text[], p_field text, p_pattern text, p_min_confidence float8, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_1024 <=> p_query)::float8, encode(c.chash, 'hex') FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id JOIN nexus.document_aspects a ON a.tenant_id = d.tenant_id AND a.doc_id = d.tumbler WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND d.alias_of = '' AND c.embedding_1024 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (p_min_confidence IS NULL OR a.confidence >= p_min_confidence) AND (p_field IS NULL OR CASE p_field WHEN 'problem_formulation' THEN a.problem_formulation WHEN 'proposed_method' THEN a.proposed_method WHEN 'experimental_datasets' THEN a.experimental_datasets WHEN 'experimental_baselines' THEN a.experimental_baselines WHEN 'experimental_results' THEN a.experimental_results END ILIKE '%' || p_pattern || '%') ORDER BY c.embedding_1024 <=> p_query LIMIT p_n $$;

rollback.sql:
DROP FUNCTION IF EXISTS nexus.search_aspect_scoped_384(vector, text[], text, text, float8, jsonb, int);
DROP FUNCTION IF EXISTS nexus.search_aspect_scoped_768(vector, text[], text, text, float8, jsonb, int);
DROP FUNCTION IF EXISTS nexus.search_aspect_scoped_1024(vector, text[], text, text, float8, jsonb, int);

changeSet.sql:
GRANT EXECUTE ON FUNCTION nexus.search_aspect_scoped_384(vector, text[], text, text, float8, jsonb, int)  TO nexus_svc;
GRANT EXECUTE ON FUNCTION nexus.search_aspect_scoped_768(vector, text[], text, text, float8, jsonb, int)  TO nexus_svc;
GRANT EXECUTE ON FUNCTION nexus.search_aspect_scoped_1024(vector, text[], text, text, float8, jsonb, int) TO nexus_svc;
